/// The configurations of a run, each with its grouping m: CFG=rs2 (default: CONFIGS_RS2, m per k), CFG=rs (CONFIGS_RS,
/// m = 1) or CFG=jl (CONFIGS_JL, m = 2); M=... overrides m.
pub fn configs() -> Vec<(&'static Config, usize)> {
    let v: Vec<(&'static Config, usize)> = match std::env::var("CFG").as_deref() {
        Ok("jl") => CONFIGS_JL.iter().map(|c| (c, 2)).collect(),
        Ok("rs") => CONFIGS_RS.iter().map(|c| (c, 1)).collect(),
        _ => CONFIGS_RS2.iter().map(|(c, m)| (c, *m)).collect(),
    };
    match std::env::var("M").ok().and_then(|x| x.parse().ok()) { Some(m) => v.into_iter().map(|(c, _)| (c, m)).collect(), None => v }
}

/// The configuration of CONFIGS_RS2 for k, with its m.
pub fn config_rs2(k: u32) -> (&'static Config, usize) {
    let (c, m) = CONFIGS_RS2.iter().find(|(c, _)| c.k == k).expect("k"); (c, *m)
}

/// log2 of the 128-bit noise of an LWE key of dimension x (q = 2^64, binary key): the curve of the paper.
pub fn log2_sigma128(x: usize) -> f64 { (-0.02591 * x as f64 + 2.77).max(-62.0) }

/// Predicted variance of the output of the rotation (binary key; m = 1: CMux form, m ≥ 2: multi-bit form, which
/// doubles the fresh errors), FFT error not included.
pub fn var_rot(n: usize, m: usize, b: usize, l: usize) -> f64 {
    let g = n as f64 / m as f64; let s2 = 2f64.powf(2.0 * LOG2_SIGMA_N);
    let key = 2.0 * l as f64 * N as f64 * (2f64.powi(2 * b as i32) + 2.0) / 12.0 * s2;
    let rnd = (1.0 + N as f64 / 2.0) * 2f64.powf(-2.0 * (l * b) as f64) / 12.0;
    ((((1 << m) - 1) as f64) * g * key + g * (1.0 - 2f64.powi(-(m as i32))) * rnd) * if m > 1 { 2.0 } else { 1.0 }
}

/// Predicted variance of the stair key switch (binary key, ρ = 1/2), as stair_var of julia/src/stair_ks.jl.
pub fn stair_var(t: usize, chain: &[(usize, u32, usize)], d: usize) -> f64 {
    let mut y = t; let mut v = 0.0;
    for &(x, b, l) in chain {
        let (k, r) = (x / d, x % d);
        let key = l as f64 * (2f64.powi(2 * b as i32) + 2.0) / 12.0 * 2f64.powf(2.0 * log2_sigma128(x));
        let rnd = 0.5 * 2f64.powf(-2.0 * (l as f64) * b as f64) / 12.0;
        v += if r == 0 { (y - x) as f64 * (key + rnd) } else { (y - k * d) as f64 * key + (y - x) as f64 * rnd };
        y = x;
    }
    v
}

/// Margin (bits) of the condition (4p̂)^2 (ν σ_out^2 + σ_KS^2) + 16 V*/(2N)^2 ≤ 1/U^2.
pub fn margin(k: u32, vout: f64, vks: f64, vterm: f64) -> f64 {
    let phat = 4f64.powi(k as i32);
    0.5 * ((1.0 / (U128 * U128)) / ((4.0 * phat).powi(2) * (NU * vout + vks) + vterm)).log2()
}
